window.__votdWeek && window.__votdWeek({"week":"2028-06-26","reading":"Alma 17–22","days":[{"d":"2028-06-26","ref":"Alma 17:3","b":"Alma","c":17,"v":3,"he":"אַךְ לֹא־זֹאת לְבַד כִּי נָתְנוּ נַפְשָׁם לִתְפִלָּה רַבָּה וְצוֹם לָכֵן הָיָה לָהֶם רוּחַ הַנְּבוּאָה וְרוּחַ הַחָזוֹן וּבְלַמְּדָם לִמְּדוּ בְּכֹחַ אֱלֹהִים וּבְשִׁלְטוֹנוֹ׃","en":"But this is not all; they had given themselves to much prayer, and fasting; therefore they had the spirit of prophecy, and the spirit of revelation, and when they taught, they taught with power and authority of God."},{"d":"2028-06-27","ref":"Alma 17:10","b":"Alma","c":17,"v":10,"he":"וַיִּפְקֹד יְהוָה אוֹתָם בְּרוּחוֹ וַיֹּאמֶר לָהֶם הִנָּחֲמוּ וַיִּנָּחֲמוּ׃","en":"And it came to pass that the Lord did visit them with his Spirit, and said unto them: Be comforted. And they were comforted."},{"d":"2028-06-28","ref":"Alma 18:23","b":"Alma","c":18,"v":23,"he":"וַיַּעַן אֹתוֹ הַמֶּלֶךְ וַיֹּאמֶר כֵּן אַאֲמִין בְּכׇל־דְּבָרֶיךָ וְכֵן נִלְכַּד בְּעׇרְמָה׃","en":"And the king answered him, and said: Yea, I will believe all thy words. And thus he was caught with guile."},{"d":"2028-06-29","ref":"Alma 18:32","b":"Alma","c":18,"v":32,"he":"וַיֹּאמֶר עַמּוֹן הֵן וְהוּא מַשְׁקִיף עַל־כׇּל־בְּנֵי הָאָדָם וְיֹדֵעַ אֶת־כׇּל־מַחְשְׁבוֹת וְיִצְרֵי הַלֵּב כִּי בְיָדוֹ נִבְרְאוּ כֻלָּם מֵרֵאשִׁית׃","en":"And Ammon said: Yea, and he looketh down upon all the children of men; and he knows all the thoughts and intents of the heart; for by his hand were they all created from the beginning."},{"d":"2028-06-30","ref":"Alma 19:9","b":"Alma","c":19,"v":9,"he":"וַיֹּאמֶר עַמּוֹן אֵלֶיהָ הֲתַאֲמִינִי בָזֹאת וַתֹּאמֶר אֵלָיו אֵין־לִי עֵד זוּלַת דְבָרְךָ וּדְבַר עֲבָדֵינוּ אַךְ מַאֲמִינָה אֲנִי כִּי יִהְיֶה כַּאֲשֶׁר אָמַרְתָּ׃","en":"And Ammon said unto her: Believest thou this? And she said unto him: I have had no witness save thy word, and the word of our servants; nevertheless I believe that it shall be according as thou hast said."},{"d":"2028-07-01","ref":"Alma 19:36","b":"Alma","c":19,"v":36,"he":"וְכֵן הֵחֵל מַעֲשֵׂה יְהוָה בְּקֶרֶב הַלָּמָנִים וְכֵן הֵחֵל יְהוָה לִשְׁפֹּךְ אֶת־רוּחוֹ עֲלֵיהֶם וְרָאִינוּ כִּי זְרוֹעוֹ נְטוּיָה אֶל כׇּל־הָעַמִּים אֲשֶׁר יָשׁוּבוּ וְיַאֲמִינוּ בִּשְׁמוֹ׃","en":"And thus the work of the Lord did commence among the Lamanites; thus the Lord did begin to pour out his Spirit upon them; and we see that his arm is extended to all people who will repent and believe on his name."},{"d":"2028-07-02","ref":"Alma 21:22","b":"Alma","c":21,"v":22,"he":"וַיַּגֵּד לָהֶם גַּם־כִּי יֵשׁ לָהֶם חֵרוּת לַעֲבֹד אֶת־יְהוָה אֱלֹהֵיהֶם כִּרְצוֹנָם בְּכׇל־מָקוֹם אֲשֶׁר הֵם שָׁם אִם בָּאָרֶץ אֲשֶׁר תַּחַת מֶמְשֶׁלֶת הַמֶּלֶךְ לָמוֹנִי׃","en":"And he also declared unto them that they might have the liberty of worshiping the Lord their God according to their desires, in whatsoever place they were in, if it were in the land which was under the reign of king Lamoni."}]});
